@Service
class NotificationService {
    private SmsSender smsSender; // optional, can stay null

    // Optional dependency wired via a setter after construction
    @Autowired(required = false)
    public void setSmsSender(SmsSender smsSender) {
        this.smsSender = smsSender;
    }

    void notifyUser(String msg) {
        if (smsSender != null) {     // guard the null before use
            smsSender.send(msg);
        }
    }
}
