// Field injection - hard to test
@Service
class OrderService {
    @Autowired
    private OrderRepository repo;  // private, can't set in a plain test

    public Order createOrder(String item) {
        return repo.save(new Order(item));
    }
}

// Constructor injection - easy to test
@Service
class OrderServiceCtor {
    private final OrderRepository repo;

    public OrderServiceCtor(OrderRepository repo) { // explicit dependency
        this.repo = repo;
    }

    public Order createOrder(String item) {
        return repo.save(new Order(item));
    }
}

// Unit test with constructor injection - no Spring
class OrderServiceTest {
    @Test
    void testCreateOrder() {
        var mockRepo = Mockito.mock(OrderRepository.class);
        var service = new OrderServiceCtor(mockRepo); // one line, no Spring
        service.createOrder("Laptop");
        verify(mockRepo).save(any());
    }
}
